update test_flow
set api_health_warning_count = #{apiHealthWarningCount},
    api_health_checked_at    = #{apiHealthCheckedAt},
    api_health_warning_codes = #{apiHealthWarningCodes}
where test_flow_id = #{testFlowId}

update test_flow
set del_status = 1
where test_flow_id = #{testFlowId}
